#include <cstring>
#include <algorithm>
#include <cstddef>

namespace alb {

struct block {
    void* ptr = nullptr;
    size_t length = 0;
    explicit operator bool() const { return ptr != nullptr; }
    void reset() { ptr = nullptr; length = 0; }
};

inline size_t round_to_alignment(size_t alignment, size_t n) {
    return (n + alignment - 1) & ~(alignment - 1);
}

inline bool is_last_used_block(const char* data, const char* p, const block& b) {
    return (static_cast<char*>(b.ptr) + b.length == p);
}

namespace stack_allocator_impl {

void deallocate(char*& p, const char* data, size_t max_size, block& b) {
    // Only reclaim memory if the block is the most recently allocated (stack top)
    if (is_last_used_block(data, p, b)) {
        p = static_cast<char*>(b.ptr);
        b.reset();
    }
}

} // namespace stack_allocator_impl
} // namespace alb

// Test
int main() {
    char buffer[256];
    alb::block b;
    b.ptr = buffer;
    b.length = 64;
    char* p = buffer + 64;  // Simulating stack top at end of block

    alb::stack_allocator_impl::deallocate(p, buffer, 256, b);

    // After deallocation, p should be back at buffer start
    // and block should be reset
    return (p == buffer && b.ptr == nullptr) ? 0 : 1;
}

